<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Sorting Algorithm Visualizer</title>
<style>
  * {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
  }

  body {
    background-color: #1a1a2e;
    color: #eee;
    font-family: Arial, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    min-height: 100vh;
    padding: 20px;
  }

  h1 {
    margin-bottom: 20px;
    color: #e94560;
    font-size: 2rem;
  }

  .controls {
    display: flex;
    gap: 12px;
    margin-bottom: 24px;
  }

  button {
    padding: 10px 24px;
    border: none;
    border-radius: 6px;
    font-size: 1rem;
    cursor: pointer;
    transition: background-color 0.2s, transform 0.1s;
  }

  button:hover {
    transform: scale(1.05);
  }

  button:active {
    transform: scale(0.97);
  }

  #sort {
    background-color: #e94560;
    color: #fff;
  }

  #sort:hover {
    background-color: #c73652;
  }

  #shuffle {
    background-color: #0f3460;
    color: #fff;
  }

  #shuffle:hover {
    background-color: #16213e;
  }

  #reset {
    background-color: #533483;
    color: #fff;
  }

  #reset:hover {
    background-color: #3d2563;
  }

  #bars {
    display: flex;
    align-items: flex-end;
    gap: 2px;
    width: 90vw;
    max-width: 900px;
    height: 400px;
    background-color: #16213e;
    border-radius: 8px;
    padding: 10px;
    box-shadow: 0 4px 20px rgba(0,0,0,0.5);
  }

  .bar {
    flex: 1;
    background: linear-gradient(to top, #e94560, #f5a623);
    border-radius: 3px 3px 0 0;
    transition: height 0.05s ease;
    min-width: 2px;
  }

  .bar.comparing {
    background: linear-gradient(to top, #00d2ff, #7efff5);
  }

  .bar.sorted-bar {
    background: linear-gradient(to top, #43e97b, #38f9d7);
  }

  .status {
    margin-top: 16px;
    font-size: 1rem;
    color: #aaa;
    min-height: 1.5em;
  }

  .speed-control {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 16px;
  }

  .speed-control label {
    color: #aaa;
  }

  input[type="range"] {
    accent-color: #e94560;
  }
</style>
</head>
<body>
<h1>Sorting Visualizer</h1>
<div class="controls">
  <button id="sort">Sort</button>
  <button id="shuffle">Shuffle</button>
  <button id="reset">Reset</button>
</div>
<div class="speed-control">
  <label for="speed">Speed:</label>
  <input type="range" id="speed" min="1" max="200" value="50">
  <span id="speed-label">50ms</span>
</div>
<div id="bars"></div>
<div class="status" id="status">Ready</div>

<script>
  // --- State ---
  const DEFAULT_SIZE = 40;
  let arr = [];
  let sortState = null;
  let animationId = null;
  let isSorting = false;

  // --- Bubble Sort Generator ---
  function* bubbleSortGen(arr) {
    const n = arr.length;
    for (let i = 0; i < n - 1; i++) {
      let swapped = false;
      for (let j = 0; j < n - i - 1; j++) {
        yield { comparing: [j, j + 1], swapped: false };
        if (arr[j] > arr[j + 1]) {
          // swap
          let tmp = arr[j];
          arr[j] = arr[j + 1];
          arr[j + 1] = tmp;
          swapped = true;
          yield { comparing: [j, j + 1], swapped: true };
        }
      }
      if (!swapped) break;
    }
    return { done: true };
  }

  // --- Sort step state ---
  let generator = null;
  let lastComparing = [];
  let isDone = false;

  function initSortState() {
    generator = bubbleSortGen(arr);
    lastComparing = [];
    isDone = false;
  }

  // --- Render ---
  function render(comparing = [], highlightSorted = false) {
    const container = document.getElementById('bars');
    container.innerHTML = '';
    const maxVal = Math.max(...arr, 1);
    arr.forEach((val, i) => {
      const bar = document.createElement('div');
      bar.className = 'bar';
      const heightPct = (val / maxVal) * 100;
      bar.style.height = heightPct + '%';

      if (comparing.includes(i)) {
        bar.classList.add('comparing');
      } else if (highlightSorted && isSorted()) {
        bar.classList.add('sorted-bar');
      }
      container.appendChild(bar);
    });
  }

  function isSorted() {
    for (let i = 0; i < arr.length - 1; i++) {
      if (arr[i] > arr[i + 1]) return false;
    }
    return true;
  }

  // --- API ---
  window.viz = {
    array() {
      return [...arr];
    },

    setArray(a) {
      stopAnimation();
      arr = [...a];
      initSortState();
      render();
      document.getElementById('status').textContent = 'Array set. Ready to sort.';
    },

    sortStep() {
      if (isDone) return true;
      if (!generator) initSortState();

      const result = generator.next();

      if (result.done || isSorted()) {
        isDone = true;
        lastComparing = [];
        render([], true);
        return true;
      }

      const step = result.value;
      if (step && step.comparing) {
        lastComparing = step.comparing;
      }

      // Check if done after this step
      if (isSorted()) {
        isDone = true;
        lastComparing = [];
        render([], true);
        return true;
      }

      render(lastComparing);
      return false;
    },

    sorted() {
      return isSorted();
    }
  };

  // --- Initialize array ---
  function generateArray(size = DEFAULT_SIZE) {
    arr = [];
    for (let i = 0; i < size; i++) {
      arr.push(Math.floor(Math.random() * 350) + 10);
    }
    initSortState();
    render();
  }

  function shuffleArray() {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    initSortState();
    render();
  }

  function stopAnimation() {
    if (animationId !== null) {
      clearTimeout(animationId);
      animationId = null;
    }
    isSorting = false;
  }

  function startAnimation() {
    if (isSorting) return;
    if (isDone || isSorted()) {
      document.getElementById('status').textContent = 'Already sorted!';
      return;
    }
    isSorting = true;
    document.getElementById('status').textContent = 'Sorting...';

    function step() {
      if (!isSorting) return;
      const delay = 201 - parseInt(document.getElementById('speed').value);
      const done = window.viz.sortStep();
      if (done) {
        isSorting = false;
        render([], true);
        document.getElementById('status').textContent = 'Sorted!';
      } else {
        animationId = setTimeout(step, delay);
      }
    }
    step();
  }

  // --- Event Listeners ---
  document.getElementById('sort').addEventListener('click', () => {
    if (isSorting) {
      stopAnimation();
      document.getElementById('status').textContent = 'Paused.';
    } else {
      startAnimation();
    }
  });

  document.getElementById('shuffle').addEventListener('click', () => {
    stopAnimation();
    shuffleArray();
    document.getElementById('status').textContent = 'Shuffled. Ready to sort.';
  });

  document.getElementById('reset').addEventListener('click', () => {
    stopAnimation();
    generateArray(DEFAULT_SIZE);
    document.getElementById('status').textContent = 'Reset. Ready to sort.';
  });

  document.getElementById('speed').addEventListener('input', function() {
    document.getElementById('speed-label').textContent = (201 - this.value) + 'ms';
  });

  // --- Init ---
  generateArray(DEFAULT_SIZE);
  document.getElementById('status').textContent = 'Ready to sort.';
</script>
</body>
</html>
